 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = [0, 0]  # up-pointing, down-pointing
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 2 and (nx,ny) not in seen:
                        seen.add((nx,ny))
                        q.append((nx,ny))
            if len(cells) != 4:
                continue
            r0, r1 = min(x for x,y in cells), max(x for x,y in cells)
            c0, c1 = min(y for x,y in cells), max(y for x,y in cells)
            if r1-r0 == 1 and c1-c0 == 2:
                top = sum(1 for x,y in cells if x == r0)
                bottom = sum(1 for x,y in cells if x == r1)
                if top == 1 and bottom == 3:
                    counts[0] += 1
                elif top == 3 and bottom == 1:
                    counts[1] += 1
    out = [[0]*6 for _ in range(3)]
    # Encode a count as nested occupied corners: TL, BL, TR, BR.
    places = ((0,0),(2,0),(0,2),(2,2))
    for side, color in enumerate((3, 1)):
        for i in range(min(counts[side], 4)):
            rr, cc = places[i]
            out[rr][cc + 3*side] = color
    return out
